@Serializable internal data class AssemblySelection(val recipe: String, val dependencies: List<String> = emptyList())
/** Authentic ORIGINAL operator subject IDs, never newly generated by a target. The
 * external evidence digest must bind the custody record before input preparation. */
@Serializable internal data class OriginalIdentityBinding(val ownerUuid: String, val outsiderUuid: String,
    val evidenceSha256: String,
    @OptIn(kotlinx.serialization.ExperimentalSerializationApi::class)
    @kotlinx.serialization.EncodeDefault(kotlinx.serialization.EncodeDefault.Mode.NEVER)
    val membershipReadback: ActivationInput? = null) {
    fun validate() {
        require(listOf(ownerUuid, outsiderUuid).all {
            runCatching { java.util.UUID.fromString(it).toString() == it }.getOrDefault(false)
        } && ownerUuid != outsiderUuid && evidenceSha256.matches(Regex("[a-f0-9]{64}")) &&
            (membershipReadback == null || membershipReadback.sha256.matches(Regex("[a-f0-9]{64}"))))
    }
}
