@Serializable internal data class AssemblySummary(val request: AssemblyRequest, val members: List<AssemblyMember>,
    val missingCapabilities: Set<String>, val globalIntegrationValidated: Boolean = false,
    val fullStackQualification: Boolean = false, val publicActivation: Boolean = false)
@Serializable internal data class AssemblyPreparationOutcome(val assemblySha256: String, val passed: Boolean,
    val bundleSha256: String? = null, val failureType: String? = null)
@Serializable internal data class AssemblyMemberIntent(val assemblySha256: String, val name: String, val specSha256: String)
internal data class PrivateRecipe(val id: String, val capabilities: Set<String>,
    val spec: (AcquiredInventory, String) -> PrivateDeploymentSpec,
    val prepare: (AcquiredInventory, Path, String, RuntimeStore) -> Path,
    val bind: (PrivateDeploymentSpec, AssemblyRequest) -> PrivateDeploymentSpec = { spec, _ -> spec },
    val prepareBound: ((AcquiredInventory, Path, PrivateDeploymentSpec) -> Path)? = null,
    val prepareWithRequest: ((AcquiredInventory, Path, PrivateDeploymentSpec, AssemblyRequest) -> Path)? = null)
internal data class AssemblyPlan(val summary: AssemblySummary, val generation: GenerationRequest,
    val inventory: AcquiredInventory, val specs: List<PrivateDeploymentSpec>, val recipes: List<PrivateRecipe>)

/** Typed existing PRIVATE recipes. Supporting database/identity copies are NOT central release wiring. */
internal class GenerationAssembly(private val recipes: List<PrivateRecipe> = catalog) {
    companion object {
        private val json = Json { ignoreUnknownKeys = false }
        val requiredCapabilities: Set<String> = ProductSelection.bundled().products.toSet() +
            setOf("openbao", "keykeeper", "worklane", "tuios", "pi",
                "keycloak-auth-gateway", "portal")
        val catalog: List<PrivateRecipe> = listOf(
            PrivateRecipe("foundation", setOf("postgres", "valkey", "ntfy"), FoundationRuntime::spec, FoundationRuntime::prepare),
            PrivateRecipe("canonical-core", setOf("postgres", "valkey", "ntfy", "planka"), CanonicalCoreRuntime::spec, CanonicalCoreRuntime::prepare),
            PrivateRecipe("canonical-providers", setOf("postgres", "valkey", "ntfy", "planka", "mariadb", "memcached", "keycloak", "firefly-iii", "caddy"),
                CanonicalCoreRuntime::providersSpec, CanonicalCoreRuntime::prepareProviders),
            PrivateRecipe("identity", setOf("keycloak"), IdentityRuntime::spec, IdentityRuntime::prepare),
            PrivateRecipe("caddy", setOf("caddy"), CaddyRuntime::spec, CaddyRuntime::prepare),
            PrivateRecipe("observability", setOf("alertmanager", "alloy", "grafana", "loki", "prometheus"), ObservabilityRuntime::spec, ObservabilityRuntime::prepare),
            PrivateRecipe("forgejo", setOf("forgejo"), ForgejoRuntime::spec, ForgejoRuntime::prepare),
            PrivateRecipe(FragmentRecipes.FORGEJO_POSTGRES, setOf("postgres", "forgejo"),
                { inventory, name -> FragmentRecipes.spec(inventory, name) },
                { _, _, _, _ -> error("Packaged preparation requires the controller-bound assembly") },
                FragmentRecipes::bindController, FragmentRecipes::prepareBound),
            PrivateRecipe(CanonicalSharedYamlGraph.RECIPE, CanonicalSharedYamlGraph.capabilities(),
                { inventory, name -> CanonicalSharedYamlGraph.spec(inventory, name) },
                { _, _, _, _ -> error("Packaged shared Quadlet preparation requires controller-bound assembly") },
                CanonicalSharedYamlGraph::bindController, CanonicalSharedYamlGraph::prepareBound,
                CanonicalSharedYamlGraph::prepareWithRequest),
            // Explicit pending candidate: never alter the active r7 recipe, its
            // historical manifests, or an already-sealed generation's binding.
            PrivateRecipe(CanonicalSharedYamlGraph.R9_ASSEMBLY_RECIPE, CanonicalSharedYamlGraph.pendingR9Capabilities(),
                { inventory, name -> CanonicalSharedYamlGraph.pendingR9Spec(inventory, name) },
                { _, _, _, _ -> error("Pending full r9 needs controller-bound whole-release assembly") },
                CanonicalSharedYamlGraph::bindController, CanonicalSharedYamlGraph::prepareBound,
                CanonicalSharedYamlGraph::prepareWithRequest),
            PrivateRecipe(CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE, CanonicalSharedYamlGraph.pendingR10Capabilities(),
                { inventory, name -> CanonicalSharedYamlGraph.pendingR10Spec(inventory, name) },
                { _, _, _, _ -> error("Full r10 needs controller-bound whole-release assembly") },
                CanonicalSharedYamlGraph::bindController, CanonicalSharedYamlGraph::prepareBound,
                CanonicalSharedYamlGraph::prepareWithRequest),
            PrivateRecipe("planka", setOf("planka"), PlankaRuntime::spec, PlankaRuntime::prepare),
            PrivateRecipe("sql-cache", setOf("mariadb", "memcached"), SqlCacheRuntime::spec, SqlCacheRuntime::prepare),
            PrivateRecipe("jellyfin", setOf("jellyfin"), JellyfinRuntime::spec, JellyfinRuntime::prepare),
            PrivateRecipe("donetick", setOf("donetick"), DonetickRuntime::spec, DonetickRuntime::prepare),
            PrivateRecipe("homeassistant", setOf("homeassistant"), HomeAssistantRuntime::spec, HomeAssistantRuntime::prepare),
            PrivateRecipe("notebook", setOf("jupyter-notebook"), NotebookRuntime::spec, NotebookRuntime::prepare),
            PrivateRecipe("qbittorrent", setOf("qbittorrent"), QbittorrentRuntime::spec, QbittorrentRuntime::prepare),
            PrivateRecipe("synapse", setOf("synapse"), SynapseRuntime::spec, SynapseRuntime::prepare),
            PrivateRecipe("matrix", setOf("synapse", "element"), MatrixRuntime::spec, MatrixRuntime::prepare),
            PrivateRecipe("matrix-identity", setOf("synapse", "element", "matrix-authentication-service"), MatrixIdentityRuntime::spec, MatrixIdentityRuntime::prepare),
            PrivateRecipe("matrix-rtc", setOf("synapse", "element", "matrix-authentication-service", "livekit"), MatrixRtcRuntime::spec, MatrixRtcRuntime::prepare),
            PrivateRecipe("opensearch", setOf("opensearch"), OpenSearchRuntime::spec, OpenSearchRuntime::prepare),
            PrivateRecipe("firefly", setOf("firefly-iii"), FireflyRuntime::spec, FireflyRuntime::prepare),
            PrivateRecipe("bookstack", setOf("bookstack"), BookStackRuntime::spec, BookStackRuntime::prepare),
            PrivateRecipe("knowledge-identity", setOf("bookstack"), KnowledgeIdentityRuntime::spec, KnowledgeIdentityRuntime::prepare),
            PrivateRecipe("livekit", setOf("livekit"), LiveKitRuntime::spec, LiveKitRuntime::prepare),
            PrivateRecipe("openbao", setOf("openbao"), OpenBaoRuntime::spec, OpenBaoRuntime::prepare),
            PrivateRecipe("mastodon", setOf("mastodon"), MastodonRuntime::spec, MastodonRuntime::prepare),
            PrivateRecipe("searxng", setOf("searxng"), SearxngRuntime::spec, SearxngRuntime::prepare),
            PrivateRecipe("erpnext", setOf("erpnext"), ErpNextRuntime::spec, ErpNextRuntime::prepare),
            PrivateRecipe("crowdsec", setOf("crowdsec"), CrowdsecRuntime::spec, CrowdsecRuntime::prepare),
            PrivateRecipe("seafile", setOf("seafile"), SeafileRuntime::spec, SeafileRuntime::prepare),
            PrivateRecipe("office", setOf("seafile", "onlyoffice"), OfficeRuntime::spec, OfficeRuntime::prepare),
            PrivateRecipe("keykeeper", setOf("keykeeper", "openbao"), KeykeeperRuntime::spec, KeykeeperRuntime::prepare),
            PrivateRecipe("node-metrics", setOf("node-exporter"), NodeMetricsRuntime::spec, NodeMetricsRuntime::prepare),
            PrivateRecipe("backup", setOf("kopia"), KopiaRuntime::spec, KopiaRuntime::prepare),
            PrivateRecipe("huly", setOf("huly"), HulyRuntime::spec, HulyRuntime::prepare),
            PrivateRecipe("jupyterhub", setOf("jupyterhub"), JupyterHubRuntime::spec, JupyterHubRuntime::prepare),
            PrivateRecipe("sogo", setOf("sogo"), { inventory, name -> SogoRuntime.spec(inventory, name) }, SogoRuntime::prepare),
            PrivateRecipe("mail", setOf("mailserver"), { _, name -> MailRuntime.spec(name) }, { _, base, name, store -> MailRuntime.prepare(base, name, store) }),
            PrivateRecipe("sogo-mail", setOf("sogo", "mailserver"), SogoMailRuntime::spec, SogoMailRuntime::prepare)
        )
        /** The full V2 recipe has a short fixed physical suffix so native DNS labels do
         * not grow with its descriptive recipe ID. Historical recipe namespaces are unchanged.
         */
        fun memberName(generation: String, recipe: String): String {
            require(recipe != "v2") { "v2 is reserved for the canonical full-release namespace" }
            return "$generation-${if (recipe in setOf("canonical-release-v2", CanonicalSharedYamlGraph.R9_ASSEMBLY_RECIPE,
                CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE)) "v2" else recipe}"
        }
        fun recipeForMember(generation: String, member: String): String {
            require(member.startsWith("$generation-")) { "Foreign recipe namespace" }
            val suffix = member.removePrefix("$generation-")
            return if (suffix == "v2") "canonical-release-v2" else suffix
        }
        fun readRequest(path: Path): AssemblyRequest = json.decodeFromString(
            GenerationRuntime.privateInput(path).decodeToString(throwOnInvalidSequence = true))
        fun readInventory(path: Path): ByteArray {
            require(Files.isRegularFile(path) && Files.size(path) in 1..2000000) { "Missing or oversized artifact inventory" }
            return Files.readAllBytes(path)
        }
    }

    fun canonicalPlan(request: AssemblyRequest, inventoryBytes: ByteArray, requireComplete: Boolean = true): CanonicalAssemblyPlan =
        CanonicalTopology.compile(plan(request, inventoryBytes), requireComplete)

    fun plan(request: AssemblyRequest, inventoryBytes: ByteArray): AssemblyPlan {
        require(request.schemaVersion == 1 && inventoryBytes.size in 1..2000000 &&
            ReleaseLocks.sha256(inventoryBytes) == request.inventorySha256) { "Assembly inventory binding mismatch" }
        val registry = recipes.associateBy { it.id }
        require(registry.size == recipes.size && recipes.all { recipe ->
            recipe.id != "v2" && recipe.id.matches(Regex("[a-z][a-z0-9-]{0,23}")) && recipe.capabilities.isNotEmpty() &&
                requiredCapabilities.containsAll(recipe.capabilities)
        }) { "Invalid typed recipe registry" }
        require(request.selections.isNotEmpty() && request.selections.size <= 64 &&
            request.selections.map { it.recipe }.distinct().size == request.selections.size &&
            request.selections.all { it.recipe in registry }) { "Unknown or duplicate assembly recipe" }
        if (request.id == "q-4d3c1cb287e5") {
            val prior=ManagedPreUnitNoStartTerminal.verify(requireNotNull(request.failedPreUnitStagePredecessor))
            val image=GenerationNormalizedWorklaneImage.requireSelected(request.managedLanes?.native?.imageArchive)
            require(request.selections.singleOrNull()?.recipe==CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE &&
                prior.predecessorPreparedNoStartSha256==requireNotNull(request.preparedNoStartPredecessor).sha256 &&
                prior.priorFailedPreparationTerminalSha256==requireNotNull(request.abandonedPreparation).terminal.sha256 &&
                image==request.managedLanes?.native?.imageArchive &&
                request.forgejoCi?.runnerBinary?.path=="/mnt/media/p0-v3/ci-runner/bin/forgejo-runner-v3.5.1") {
                "New target must bind all three predecessors, normalized Worklane OCI and executable native CI source"
            }
        } else if (request.id !in setOf(GenerationAfterNativeImportLineage.generation,
                GenerationAfterCapacityRefusalLineage.generation,GenerationAfterQ273Lineage.generation,
                GenerationAfterQ583Lineage.generation,GenerationAfterQ9bLineage.generation,
                GenerationAfterQ07Lineage.generation))
            require(request.failedPreUnitStagePredecessor==null)
        if (request.id in setOf(GenerationAfterNativeImportLineage.generation,
                GenerationAfterCapacityRefusalLineage.generation,GenerationAfterQ273Lineage.generation,
                GenerationAfterQ583Lineage.generation,GenerationAfterQ9bLineage.generation,
                GenerationAfterQ07Lineage.generation)) {
            GenerationAfterNativeImportLineage.verify(
                requireNotNull(request.uncertainNativeImportPredecessor),
                requireNotNull(request.isolatedRootlessProbePredecessor))
            val prior=ManagedPreUnitNoStartTerminal.verify(requireNotNull(request.failedPreUnitStagePredecessor))
            require(prior.predecessorPreparedNoStartSha256==requireNotNull(request.preparedNoStartPredecessor).sha256 &&
                prior.priorFailedPreparationTerminalSha256==requireNotNull(request.abandonedPreparation).terminal.sha256 &&
                request.selections.singleOrNull()?.recipe==CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE &&
                GenerationNormalizedWorklaneImage.requireSelected(request.managedLanes?.native?.imageArchive)==
                    request.managedLanes?.native?.imageArchive &&
                request.forgejoCi?.runnerBinary?.path=="/mnt/media/p0-v3/ci-runner/bin/forgejo-runner-v3.5.1")
        } else require(request.uncertainNativeImportPredecessor==null && request.isolatedRootlessProbePredecessor==null)
        if (request.id in setOf(GenerationAfterCapacityRefusalLineage.generation,
                GenerationAfterQ273Lineage.generation,GenerationAfterQ583Lineage.generation,
                GenerationAfterQ9bLineage.generation,GenerationAfterQ07Lineage.generation))
            GenerationAfterCapacityRefusalLineage.verify(
                requireNotNull(request.qc3PreparedNoStartPredecessor),
                requireNotNull(request.uncertainNativeImportPredecessor),
                requireNotNull(request.isolatedRootlessProbePredecessor))
        else require(request.qc3PreparedNoStartPredecessor==null)
        if (request.id in setOf(GenerationAfterQ273Lineage.generation,
                GenerationAfterQ583Lineage.generation,GenerationAfterQ9bLineage.generation,
                GenerationAfterQ07Lineage.generation)) {
            GenerationAfterQ273Lineage.verify(requireNotNull(request.q273UncertainImportPredecessor),
                requireNotNull(request.qc3PreparedNoStartPredecessor),
                requireNotNull(request.uncertainNativeImportPredecessor),
                requireNotNull(request.isolatedRootlessProbePredecessor))
            WorklaneLateBrokerImportProof.verifySelected(requireNotNull(request.managedLanes).native.worklane)
        } else require(request.q273UncertainImportPredecessor==null)
        if (request.id in setOf(GenerationAfterQ583Lineage.generation,
                GenerationAfterQ9bLineage.generation,GenerationAfterQ07Lineage.generation)) {
            GenerationAfterQ583Lineage.verify(requireNotNull(request.q583PreparedNoStartPredecessor),
                requireNotNull(request.isolatedFullWorklanePreparePredecessor),
                requireNotNull(request.q273UncertainImportPredecessor),
                requireNotNull(request.qc3PreparedNoStartPredecessor),
                requireNotNull(request.uncertainNativeImportPredecessor),
                requireNotNull(request.isolatedRootlessProbePredecessor))
            WorklaneLateBrokerImportProof.verifySelected(requireNotNull(request.managedLanes).native.worklane)
        } else require(request.q583PreparedNoStartPredecessor==null &&
            request.isolatedFullWorklanePreparePredecessor==null)
        if (request.id in setOf(GenerationAfterQ9bLineage.generation,GenerationAfterQ07Lineage.generation))
            GenerationAfterQ9bLineage.verify(requireNotNull(request.q9bColdPreparedUninstalledPredecessor),
                requireNotNull(request.q583PreparedNoStartPredecessor),
                requireNotNull(request.isolatedFullWorklanePreparePredecessor),
                requireNotNull(request.q273UncertainImportPredecessor),
                requireNotNull(request.qc3PreparedNoStartPredecessor),
                requireNotNull(request.uncertainNativeImportPredecessor),
                requireNotNull(request.isolatedRootlessProbePredecessor))
        else require(request.q9bColdPreparedUninstalledPredecessor==null)
        if (request.id==GenerationAfterQ07Lineage.generation)
            GenerationAfterQ07Lineage.verify(requireNotNull(request.q07PartialInstalledPredecessor),
                requireNotNull(request.q9bColdPreparedUninstalledPredecessor),
                requireNotNull(request.q583PreparedNoStartPredecessor),
                requireNotNull(request.isolatedFullWorklanePreparePredecessor),
                requireNotNull(request.q273UncertainImportPredecessor),
                requireNotNull(request.qc3PreparedNoStartPredecessor),
                requireNotNull(request.uncertainNativeImportPredecessor),
                requireNotNull(request.isolatedRootlessProbePredecessor))
        else require(request.q07PartialInstalledPredecessor==null)
        if (request.id == "q-dd36ebcf43ef") {
            val predecessor=PreparedNoStartTerminal.verify(requireNotNull(request.preparedNoStartPredecessor))
            require(request.selections.singleOrNull()?.recipe == CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE &&
                predecessor.earlierFailedPreparationTerminalSha256 ==
                    requireNotNull(request.abandonedPreparation).terminal.sha256 &&
                request.forgejoCi?.runnerBinary?.path ==
                    "/mnt/media/p0-v3/ci-runner/bin/forgejo-runner-v3.5.1" &&
                requireNotNull(request.forgejoCi).runnerBinary.sha256 == predecessor.runnerBinarySha256 &&
                request.quadletControllerSha256==request.releaseCandidateSha256) {
                "Fresh successor must bind passed-preparation no-start, earlier failed-preparation terminal and executable built CI source"
            }
        } else if (request.id !in setOf("q-4d3c1cb287e5",GenerationAfterNativeImportLineage.generation,
                GenerationAfterCapacityRefusalLineage.generation,GenerationAfterQ273Lineage.generation,
                GenerationAfterQ583Lineage.generation,GenerationAfterQ9bLineage.generation,
                GenerationAfterQ07Lineage.generation))
            require(request.preparedNoStartPredecessor == null)
        if (request.id == "q-5712d9335843" && request.abandonedPreparation != null) require(
            request.selections.singleOrNull()?.recipe == CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE) {
            "Successor must select the versioned Planka r2 full graph; old r9 source request is unsealed and superseded"
        }
        if (request.selections.any { it.recipe in setOf(CanonicalSharedYamlGraph.R9_ASSEMBLY_RECIPE,
                CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE) }) {
            requireNotNull(request.gatewayDenialProducer).validate()
            if (request.selections.singleOrNull()?.recipe == CanonicalSharedYamlGraph.R10_ASSEMBLY_RECIPE) {
                GenerationFreshPlankaGrant.original(request.id, requireNotNull(request.freshPlankaActorGrant))
            } else require(request.freshPlankaActorGrant == null)
            require(request.store == RuntimeStore.CANONICAL_V2 &&
                request.forgejoCi?.graphOwnedLateUpstream == true &&
                request.forgejoCi.freshIssuerBootstrap &&
                request.rssPlan != null && request.managedLanes != null &&
                request.freshIdentity != null && request.originalIdentity == null &&
                request.baoBootstrapOperation?.also { it.validate(request.id) } != null &&
                request.baoBootstrapToken == null && request.mastodonRedisScripts != null &&
                !request.portalRoutes.isNullOrEmpty() &&
                request.quadletControllerSha256 != null && request.releaseCandidateSha256 != null) {
                "Complete r9 request must bind fresh CI/managed/RSS/identity/source and a future gateway denial producer before an envelope"
            }
        } else require(request.gatewayDenialProducer == null)
        request.predecessorDisposition?.let {
            require(request.id == GenerationCiPreEffectContinuation.GENERATION)
            GenerationCiPreEffectContinuation.verify(GenerationRuntime.BASE.resolve(request.id), it)
        }
        request.memberPredecessorDisposition?.let {
            require(request.id == GenerationCiPreEffectContinuation.GENERATION && request.predecessorDisposition != null)
            GenerationCiMemberPreEffectContinuation.verify(GenerationRuntime.BASE.resolve(request.id),it)
        }
        request.abandonedPreparation?.let {
            require(request.predecessorDisposition==null && request.memberPredecessorDisposition==null &&
                request.quadletControllerSha256==request.releaseCandidateSha256)
            AbandonedPreparationLineages.inspect(request.id,requireNotNull(request.quadletControllerSha256),it)
        }
        val capabilities = request.selections.flatMap { registry.getValue(it.recipe).capabilities }
        require(capabilities.distinct().size == capabilities.size) { "Conflicting primary product ownership; select one composite, not duplicate proofs" }
        val generation = GenerationRequest(id = request.id, candidateSha256 = request.candidateSha256,
            members = request.selections.map { selected -> GenerationMember(memberName(request.id, selected.recipe),
                selected.dependencies.map { memberName(request.id, it) }) }, diskReservationMiB = request.diskReservationMiB,
            memoryHeadroomMiB = request.memoryHeadroomMiB, diskHeadroomMiB = request.diskHeadroomMiB, purpose = request.purpose, store = request.store, rssPlan = request.rssPlan,
            managedLanes = request.managedLanes, forgejoCi = request.forgejoCi,
            baoBootstrapOperation = request.baoBootstrapOperation,
            releaseCandidateSha256 = request.releaseCandidateSha256,
            gatewayDenialProducer = request.gatewayDenialProducer,
            predecessorDisposition = request.predecessorDisposition,
            memberPredecessorDisposition = request.memberPredecessorDisposition,
            abandonedPreparation = request.abandonedPreparation,
            preparedNoStartPredecessor = request.preparedNoStartPredecessor,
            failedPreUnitStagePredecessor = request.failedPreUnitStagePredecessor,
            uncertainNativeImportPredecessor = request.uncertainNativeImportPredecessor,
            isolatedRootlessProbePredecessor = request.isolatedRootlessProbePredecessor,
            qc3PreparedNoStartPredecessor = request.qc3PreparedNoStartPredecessor,
            q273UncertainImportPredecessor = request.q273UncertainImportPredecessor,
            q583PreparedNoStartPredecessor = request.q583PreparedNoStartPredecessor,
            isolatedFullWorklanePreparePredecessor = request.isolatedFullWorklanePreparePredecessor,
            q9bColdPreparedUninstalledPredecessor = request.q9bColdPreparedUninstalledPredecessor,
            q07PartialInstalledPredecessor = request.q07PartialInstalledPredecessor,
            freshPlankaActorGrant = request.freshPlankaActorGrant,
            workingBudget = request.workingBudget)
        val order = GenerationRuntime.validateScope(generation)
        val inventory = json.decodeFromString<AcquiredInventory>(inventoryBytes.decodeToString(throwOnInvalidSequence = true))
        require(inventory.schemaVersion == 1 && inventory.images.size in 1..256 &&
            inventory.images.map { it.product }.distinct().size == inventory.images.size) { "Invalid assembly inventory" }
        // v2 is the fixed physical member name for the pending r9 whole-family
        // selection too; use the original immutable request to disambiguate it.
        val adapters = order.map { member -> registry.getValue(request.selections.single {
            memberName(request.id, it.recipe) == member.name
        }.recipe) }
        // Resolve and validate EVERY recipe before generating ANY credentials or files.
        val specs = adapters.zip(order).map { (adapter, member) -> adapter.bind(adapter.spec(inventory, member.name), request).copy(store = request.store).also {
            require(it.name == member.name) { "Recipe returned foreign namespace" }
            PrivateDeployment.validate(it)
        } }
        specs.filter { it.executionBackend == RuntimeExecutionBackend.QUADLET_V2 }.forEach {
            require(request.store == RuntimeStore.CANONICAL_V2) { "Quadlet recipes require the canonical store" }
        }
        require(request.diskReservationMiB >= specs.sumOf { it.volumes.size.toLong() * 1024 } +
            GenerationManagedComponents.diskReservationMiB(generation)) { "Assembly disk reservation below state minimum" }
        val members = specs.indices.map { index ->
            val spec = specs[index]
            val state = spec.volumes.map { volume ->
                val writers = spec.processes.filter { process -> process.volumes.any { it.volume == volume.id } }.map { it.id }.sorted()
                require(writers.isNotEmpty()) { "Unowned assembly state" }
                AssemblyState(volume.id, volume.userId, writers)
            }
            val inputs = PrivateDeployment.inputNames(spec).map { name -> AssemblyInput(name,
                spec.processes.filter { it.environmentFile == name || it.files.any { file -> file.file == name } }.map { it.id }.sorted()) }
            AssemblyMember(adapters[index].id, spec.name, order[index].dependencies, adapters[index].capabilities,
                ReleaseLocks.sha256(json.encodeToString(spec).toByteArray()), spec.processes.associate { it.image to it.imageId }.also { images ->
                    require(spec.processes.all { images[it.image] == it.imageId }) { "Conflicting image identities" }
                }, spec.processes.filterNot { it.oneShot }.map { it.id }, spec.processes.filter { it.oneShot }.map { it.id }, state, inputs)
        }
        return AssemblyPlan(AssemblySummary(request, members,
            requiredCapabilities - capabilities.toSet() - GenerationManagedComponents.capabilities(generation)),
            generation, inventory, specs, adapters)
    }
}
